package me.zhengjie.iou;

import me.zhengjie.iou.domain.*;
import me.zhengjie.iou.domain.dto.IouNoteConditions;
import me.zhengjie.iou.service.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class IouRepaymentCalculatorTest {
    private final IouRepaymentCalculator calc=new IouRepaymentCalculator(new IouNoteOptions());
    static IouNoteConditions standard(String method){IouNoteConditions c=new IouNoteConditions();c.setCreatorRole("lender");c.setPrincipalAmount("10000.00");c.setLoanDate("2026-01-31");c.setFirstDueDate("2026-02-28");c.setInstallmentCount(12);c.setRepaymentCycleMonths(1);c.setRepaymentMethod(method);c.setInterestFree(false);c.setAnnualRate("0.06000000");c.setPrepaymentRule("actual");return c;}
    private void invariant(IouRepaymentCalculator.Quote q){BigDecimal p=BigDecimal.ZERO,i=BigDecimal.ZERO,t=BigDecimal.ZERO;for(IouNotePlan row:q.getPlan()){assertEquals(0,row.getPrincipalAmount().add(row.getInterestAmount()).compareTo(row.getTotalAmount()));assertTrue(row.getPrincipalAmount().signum()>=0);assertTrue(row.getInterestAmount().signum()>=0);p=p.add(row.getPrincipalAmount());i=i.add(row.getInterestAmount());t=t.add(row.getTotalAmount());}assertEquals(0,p.compareTo(new BigDecimal(q.getSummary().get("principalAmount"))));assertEquals(0,i.compareTo(new BigDecimal(q.getSummary().get("interestAmount"))));assertEquals(0,t.compareTo(new BigDecimal(q.getSummary().get("totalAmount"))));assertEquals(0,q.getPlan().get(q.getPlan().size()-1).getRemainingPrincipal().signum());}
    @Test void allStandardMethodsKeepMoneyAndMonthEndInvariants(){for(String m:Arrays.asList("annuity","principal","interest")){IouRepaymentCalculator.Quote q=calc.calculate(standard(m));invariant(q);assertEquals("2026-03-31",q.getPlan().get(1).getDueDate().toString());}}
    @Test void annuityMatchesIndependentKnownSchedule(){IouRepaymentCalculator.Quote q=calc.calculate(standard("annuity"));assertEquals("860.66",q.getSummary().get("firstAmount"));assertEquals("50.00",q.getPlan().get(0).getInterestAmount().toPlainString());invariant(q);}
    @Test void nonRegularFirstUsesActualDays(){IouNoteConditions c=standard("principal");c.setFirstDueDate("2026-02-15");assertEquals("24.66",calc.calculate(c).getPlan().get(0).getInterestAmount().toPlainString());}
    @Test void quarterlyUsesThreeTwelfths(){IouNoteConditions c=standard("principal");c.setRepaymentCycleMonths(3);c.setFirstDueDate("2026-04-30");assertEquals("150.00",calc.calculate(c).getPlan().get(0).getInterestAmount().toPlainString());}
    @Test void onceSpansLeapDayUsingFixed365(){IouNoteConditions c=standard("once");c.setLoanDate("2028-02-28");c.setDueDate("2028-03-01");c.setFirstDueDate(null);c.setInstallmentCount(null);c.setRepaymentCycleMonths(null);assertEquals("3.29",calc.calculate(c).getSummary().get("interestAmount"));}
    @Test void tinyFixedInterestNeverGoesNegative(){IouNoteConditions c=standard("flat");c.setAnnualRate("0");c.setFixedInterestAmount("0.02");IouRepaymentCalculator.Quote q=calc.calculate(c);invariant(q);assertEquals("0.02",q.getSummary().get("interestAmount"));}
    @Test void noInterestNormalizesAverageMethods(){for(String method:Arrays.asList("annuity","principal","flat")){IouNoteConditions c=standard(method);c.setInterestFree(true);c.setAnnualRate("0");IouRepaymentCalculator.Quote q=calc.calculate(c);invariant(q);assertEquals("principal",q.getConditions().getRepaymentMethod());assertEquals("0.00",q.getSummary().get("interestAmount"));}}
    @Test void interestOnlyDefersAllPrincipal(){IouRepaymentCalculator.Quote q=calc.calculate(standard("interest"));assertEquals(0,q.getPlan().get(0).getPrincipalAmount().signum());assertEquals("10000.00",q.getPlan().get(11).getPrincipalAmount().toPlainString());}
    @Test void customAcceptsZeroPrincipalButRequiresExactTotal(){IouNoteConditions c=standard("custom");c.setFirstDueDate(null);c.setInstallmentCount(null);c.setRepaymentCycleMonths(null);List<IouNoteConditions.CustomPeriod>rows=new ArrayList<>();for(int x=0;x<2;x++){IouNoteConditions.CustomPeriod p=new IouNoteConditions.CustomPeriod();p.setDueDate(x==0?"2026-02-28":"2026-03-31");p.setPrincipalAmount(x==0?"0.00":"10000.00");rows.add(p);}c.setCustomPlan(rows);invariant(calc.calculate(c));rows.get(1).setPrincipalAmount("9999.99");assertThrows(IouBusinessException.class,()->calc.calculate(c));}
    @Test void rejectsConflictingInputsAndInvalidDates(){IouNoteConditions c=standard("annuity");c.setInterestFree(true);assertThrows(IouBusinessException.class,()->calc.calculate(c));c.setInterestFree(false);c.setLoanDate("2026-02-30");assertThrows(IouBusinessException.class,()->calc.calculate(c));c.setLoanDate("2026-01-31");c.setDueDate("2027-01-31");assertThrows(IouBusinessException.class,()->calc.calculate(c));}
    @Test void rejectsOverflowPrecisionAndRateByConfiguration(){IouNoteConditions c=standard("principal");for(String amount:Arrays.asList("0","-1","1.001","1e5","100000000.01")){c.setPrincipalAmount(amount);assertThrows(IouBusinessException.class,()->calc.calculate(c));}c.setPrincipalAmount("1");c.setAnnualRate("1.01");assertThrows(IouBusinessException.class,()->calc.calculate(c));}
    @Test void deterministicSmallAmountTailAllocation(){IouNoteConditions c=standard("principal");c.setPrincipalAmount("0.01");c.setAnnualRate("0");c.setInterestFree(true);IouRepaymentCalculator.Quote q=calc.calculate(c);invariant(q);assertEquals("0.01",q.getPlan().get(11).getPrincipalAmount().toPlainString());}
    @Test void zeroRateIsStableWhenReloadedAsInterestFree(){IouNoteConditions c=standard("annuity");c.setAnnualRate("0");c.setInstallmentCount(6);IouRepaymentCalculator.Quote first=calc.calculate(c);assertTrue(first.getConditions().getInterestFree());assertEquals("principal",first.getConditions().getRepaymentMethod());assertEquals("1666.66",first.getPlan().get(0).getPrincipalAmount().toPlainString());IouRepaymentCalculator.Quote reloaded=calc.calculate(first.getConditions());assertEquals(first.getSummary(),reloaded.getSummary());for(int i=0;i<6;i++)assertEquals(first.getPlan().get(i).getTotalAmount(),reloaded.getPlan().get(i).getTotalAmount());}
}
